const projects=[];
for(const item of $input.all()){
  const value=item.json??{};
  const candidates=Array.isArray(value.payloads)?value.payloads:[value];
  for(const candidate of candidates){
    if(candidate?.kind!=='project'||!candidate?.projectSlug) continue;
    const workflowEntries=Object.entries(candidate.technicalFiles??{})
      .filter(([file])=>file.startsWith('workflows/')&&file.endsWith('.sanitized.json'));
    if(workflowEntries.length===0) throw new Error('Nenhum workflow sanitizado encontrado para '+candidate.projectSlug);
    const workflows=workflowEntries.map(([file,content])=>{
      try{return {file,workflow:JSON.parse(content)};}
      catch{throw new Error('JSON sanitizado inválido: '+file);}
    });
    let projectManifest={};
    try{projectManifest=JSON.parse(candidate.technicalFiles?.['project.json']??'{}');}
    catch{throw new Error('project.json inválido para '+candidate.projectSlug);}
    const notionContext=candidate.notionContext??{enabled:false,status:'not-configured',pages:[]};
    const aiInput={
      project:{
        projectSlug:candidate.projectSlug,
        title:candidate.title,
        documentationLayout:'separated',
        functionalHash:candidate.functionalHash,
        components:candidate.components,
        dependencies:candidate.dependencies,
        manifest:projectManifest,
        repositoryContext:candidate.repositoryContext??null,
        previousDocumentation:candidate.previousDocumentation??null,
        notionMeetings:{
          enabled:Boolean(notionContext.enabled),
          status:notionContext.status??'not-configured',
          truncated:Boolean(notionContext.truncated),
          pages:Array.isArray(notionContext.pages)?notionContext.pages:[]
        }
      },
      workflows
    };
    projects.push({json:{...candidate,documentationLayout:'separated',documentationMode:'bootstrap',aiInput}});
  }
}
if(projects.length===0) throw new Error('Nenhum projeto sanitizado recebido do Core.');
return projects;

const source=$('Preparar dados sanitizados').item.json;
let generated=$json.output??$json;
if(typeof generated==='string'){
  try{generated=JSON.parse(generated);}
  catch{throw new Error('A IA não retornou JSON válido.');}
}
const fenceMarker=String.fromCharCode(96).repeat(3);
const stripFence=value=>{
  let text=String(value??'').trim();
  if(text.startsWith(fenceMarker)) text=text.slice(fenceMarker.length).replace(/^(?:markdown|md|mermaid)?\s*/i,'');
  if(text.endsWith(fenceMarker)) text=text.slice(0,-fenceMarker.length);
  return text.trim();
};
const normalizeMermaid=value=>String(value??'')
  .split('\n')
  .map(line=>line.replace(
    /(\b[A-Za-z_][A-Za-z0-9_-]*)\[(?!["\[\(\{])([^\]\n]+)\]/g,
    (match,nodeId,label)=>nodeId+'["'+label.trim().replace(/"/g,"'")+'"]'
  ))
  .join('\n');
const validateHeadings=(markdown,headings,label)=>{
  let previousIndex=-1;
  const missing=[];
  for(const heading of headings){
    const index=markdown.indexOf(heading);
    if(index<0) missing.push(heading);
    else if(index<=previousIndex) throw new Error(label+' contém títulos obrigatórios fora de ordem: '+heading);
    else previousIndex=index;
  }
  if(missing.length) throw new Error(label+' sem títulos obrigatórios: '+missing.join(', '));
  const lines=markdown.split('\n');
  for(const heading of headings){
    const start=lines.findIndex(line=>line.trim()===heading);
    if(start<0) continue;
    const level=heading.match(/^#+/)?.[0].length??1;
    let end=lines.length;
    for(let index=start+1;index<lines.length;index++){
      const match=lines[index].match(/^(#+)\s/);
      if(match&&match[1].length<=level){end=index;break;}
    }
    const body=lines.slice(start+1,end).filter(line=>line.trim()&&!/^#+\s/.test(line)).join('').trim();
    if(!body) throw new Error(label+' contém seção obrigatória vazia: '+heading);
  }
};
const technicalHeadings=[
  '## Visão técnica','## Objetivo e escopo','## Usuários e canais','## Gatilhos e entradas',
  '## Fluxo principal','## Integrações e APIs','## Modelo e lógica de IA','## Dados e persistência',
  '## Saídas','## Operação e observabilidade','## Tratamento de erros','## Limitações técnicas',
  '## Pontos técnicos que precisam de confirmação'
];
const internalHeadings=[
  '## Identificação do projeto','### Nome do projeto','### Tipo de projeto','### Data de início',
  '### Término ou status','### Responsáveis','### Repositório','## Cliente ou empresa',
  '### Nome do cliente','### Descrição da empresa','### Perfil e dinâmica de relacionamento',
  '#### Flexibilidade com prazos','#### Frequência de respostas','#### Pedidos fora do escopo',
  '## Descrição do produto','## Escopo e decisões','## Riscos internos','## Pendências internas'
];
const requiredWorkflowHeadings=[
  '## Papel no projeto','## Gatilhos e entradas','## Etapas principais','## Integrações e credenciais',
  '## Dependências','## Saídas','## Tratamento de erros','## Limitações e pontos de confirmação'
];
const projectSummary=stripFence(generated.projectSummary).replace(/^#+\s.*$/gm,'').trim();
const technicalMarkdown=stripFence(generated.technicalMarkdown);
const internalMarkdown=stripFence(generated.internalMarkdown);
const architectureMermaid=normalizeMermaid(stripFence(generated.architectureMermaid));
if(projectSummary.length<20) throw new Error('Resumo do projeto ausente ou curto demais.');
if(!technicalMarkdown.startsWith('# Documentação técnica')) throw new Error('Documento técnico precisa começar com # Documentação técnica.');
if(!internalMarkdown.startsWith('# Contexto interno')) throw new Error('Documento interno precisa começar com # Contexto interno.');
if(/^## (?:Workflows documentados|Arquitetura do fluxo)\s*$/im.test(technicalMarkdown)){
  throw new Error('A IA não deve criar o índice nem a arquitetura; essas seções são inseridas deterministicamente.');
}
validateHeadings(technicalMarkdown,technicalHeadings,'Documento técnico');
validateHeadings(internalMarkdown,internalHeadings,'Documento interno');
if(!/^(flowchart|graph)\s+(TD|TB|BT|RL|LR)\b/i.test(architectureMermaid)){
  throw new Error('Diagrama gerado pela IA não contém um grafo Mermaid válido.');
}
if(/(\b[A-Za-z_][A-Za-z0-9_-]*)\[(?!")([^\]\n]+)\]/.test(architectureMermaid)){
  throw new Error('Diagrama Mermaid contém rótulo retangular sem aspas. Use ID["rótulo"].');
}
const expectedComponents=Array.isArray(source.components)?source.components:[];
if(expectedComponents.length===0) throw new Error('Projeto sem componentes para documentar.');
const expectedBySlug=new Map(expectedComponents.map(component=>[String(component.workflowSlug),component]));
const workflowDocuments=Array.isArray(generated.workflowDocuments)?generated.workflowDocuments:[];
const documentsBySlug=new Map();
for(const document of workflowDocuments){
  const workflowSlug=String(document?.workflowSlug??'').trim();
  if(!expectedBySlug.has(workflowSlug)) throw new Error('Documentação recebida para workflow desconhecido: '+workflowSlug);
  if(documentsBySlug.has(workflowSlug)) throw new Error('Documentação duplicada para workflow: '+workflowSlug);
  const markdown=stripFence(document?.markdown);
  if(!markdown.startsWith('# ')) throw new Error('Documento de '+workflowSlug+' precisa começar com H1.');
  validateHeadings(markdown,requiredWorkflowHeadings,'Documento de '+workflowSlug);
  documentsBySlug.set(workflowSlug,markdown);
}
const missingDocuments=[...expectedBySlug.keys()].filter(slug=>!documentsBySlug.has(slug));
const roleLabels={agent:'Agente',tool:'Tool',subflow:'Subworkflow',workflow:'Workflow'};
const workflowSources=new Map((source.aiInput?.workflows??[]).map(entry=>{
  const match=String(entry?.file??'').match(/^workflows\/(.+)\.sanitized\.json$/);
  return [match?.[1]??'',entry?.workflow??{}];
}).filter(([slug])=>slug));
const cleanLabel=value=>String(value??'').replace(/[\r\n]+/g,' ').trim();
const listOr=(values,fallback)=>values.length?values.map(value=>'- '+value).join('\n'):fallback;
for(const workflowSlug of missingDocuments){
  const component=expectedBySlug.get(workflowSlug)??{};
  const workflow=workflowSources.get(workflowSlug)??{};
  const nodes=Array.isArray(workflow.nodes)?workflow.nodes:[];
  const connections=workflow.connections??{};
  const triggers=nodes.filter(item=>/(trigger|webhook)/i.test(item.type??''))
    .map(item=>cleanLabel(item.name)+' (\x60'+cleanLabel(item.type)+'\x60)');
  const steps=nodes.slice(0,40).map((item,index)=>(index+1)+'. '+cleanLabel(item.name)+' — \x60'+cleanLabel(item.type)+'\x60.');
  const credentialTypes=[...new Set(nodes.flatMap(item=>Object.keys(item.credentials??{})))].sort();
  const integrationTypes=[...new Set(nodes.map(item=>cleanLabel(item.type)
    .replace(/^@?n8n-nodes-base\./,'').replace(/^@n8n\/n8n-nodes-langchain\./,''))
    .filter(type=>type&&!/^(code|set|if|switch|merge|splitInBatches|stickyNote)$/i.test(type)))].sort();
  const dependencies=(source.dependencies??[]).filter(item=>item.source===component.componentId)
    .map(item=>(item.relation??'dependsOn')+' → '+(item.target??item.targetWorkflowId??'dependência externa')+' via '+(item.viaNode??'node não informado'));
  const connectedSources=new Set(Object.entries(connections)
    .filter(([,value])=>Array.isArray(value?.main)&&value.main.some(branch=>Array.isArray(branch)&&branch.length))
    .map(([name])=>name));
  const terminalNodes=nodes.map(item=>cleanLabel(item.name)).filter(name=>name&&!connectedSources.has(name));
  const errorNodes=nodes.filter(item=>item.retryOnFail||item.onError)
    .map(item=>cleanLabel(item.name)+' — '+(item.onError??(item.retryOnFail?'retryOnFail':'configuração de erro')));
  const markdown=[
    '# '+cleanLabel(component.name??workflow.name??workflowSlug),'',
    '> Documento-base gerado deterministicamente porque a IA omitiu este workflow. Revisão humana obrigatória.','',
    '## Papel no projeto','',
    (roleLabels[component.role]??component.role??'Workflow')+' do projeto. O papel funcional detalhado precisa de confirmação a partir dos nodes abaixo.','',
    '## Gatilhos e entradas','',listOr(triggers,'Nenhum gatilho explícito foi identificado; confirme como este workflow é chamado.'),'',
    '## Etapas principais','',listOr(steps,'Nenhum node foi encontrado no snapshot sanitizado.'),'',
    '## Integrações e credenciais','',
    'Integrações identificadas: '+(integrationTypes.join(', ')||'nenhuma integração externa identificada')+'.','',
    'Tipos de credencial: '+(credentialTypes.join(', ')||'nenhum tipo de credencial identificado')+'.','',
    '## Dependências','',listOr(dependencies,'Nenhuma dependência entre workflows foi comprovada pelo Core.'),'',
    '## Saídas','',listOr(terminalNodes,'Nenhum node terminal foi identificado; confirme as saídas esperadas.'),'',
    '## Tratamento de erros','',listOr(errorNodes,'Nenhuma configuração explícita de retry ou onError foi identificada.'),'',
    '## Limitações e pontos de confirmação','',
    '- Confirmar o papel funcional, entradas, saídas e regras de negócio deste workflow.','',
    '- Substituir este documento-base por uma descrição revisada quando necessário.'
  ].join('\n');
  validateHeadings(markdown,requiredWorkflowHeadings,'Fallback de '+workflowSlug);
  documentsBySlug.set(workflowSlug,markdown);
}
const workflowIndex=[
  '## Workflows documentados','',
  ...expectedComponents.map(component=>'- ['+component.name+'](workflows/'+component.workflowSlug+'.md) — '+(roleLabels[component.role]??component.role??'Workflow')+'.')
].join('\n');
const fence=String.fromCharCode(96).repeat(3);
const architectureSection=['## Arquitetura do fluxo','',fence+'mermaid',architectureMermaid,fence].join('\n');
const marker='## Integrações e APIs';
const markerIndex=technicalMarkdown.indexOf(marker);
const technicalWithGenerated=technicalMarkdown.slice(0,markerIndex).trim()+'\n\n'+workflowIndex+'\n\n'+architectureSection+'\n\n'+technicalMarkdown.slice(markerIndex).trim();
const extractSection=(markdown,heading)=>{
  const lines=markdown.split('\n');
  const start=lines.findIndex(line=>line.trim()===heading);
  if(start<0) throw new Error('Seção ausente ao montar README: '+heading);
  const level=heading.match(/^#+/)?.[0].length??1;
  let end=lines.length;
  for(let index=start+1;index<lines.length;index++){
    const match=lines[index].match(/^(#+)\s/);
    if(match&&match[1].length<=level){end=index;break;}
  }
  const body=lines.slice(start+1,end).join('\n').trim();
  if(!body) throw new Error('Seção vazia ao montar README: '+heading);
  return body;
};
const safeTitle=String(source.title??source.projectSlug??'Projeto n8n').replace(/[\r\n#]+/g,' ').trim();
const decisionsTemplate=[
  '# Decisões e aprendizados — '+safeTitle,'',
  'Registro vivo para consultores documentarem decisões relevantes e aprendizados obtidos durante o projeto.','',
  '## Como usar','',
  '- Crie uma nova entrada para cada decisão ou aprendizado relevante.',
  '- Não apague decisões substituídas; altere o status e referencie a nova entrada.',
  '- Registre fatos verificáveis e adicione links para PRs, issues, workflows ou documentos quando existirem.','',
  '## Registro','',
  '### AAAA-MM-DD — Título da decisão ou aprendizado','',
  '- **Status:** proposta | aceita | substituída | aprendizado',
  '- **Tipo:** arquitetura | produto | processo | operação',
  '- **Responsáveis:** preencher','',
  '#### Contexto','',
  'Descreva o problema, restrição ou situação que motivou o registro.','',
  '#### Decisão ou aprendizado','',
  'Registre o que foi decidido ou aprendido e por quê.','',
  '#### Alternativas consideradas','',
  '- Alternativa analisada e motivo para aceitar ou rejeitar.','',
  '#### Consequências','',
  '- Impactos positivos, negativos, riscos e limitações.','',
  '#### Evidências e referências','',
  '- Links para PRs, issues, workflows, métricas ou documentos relacionados.','',
  '#### Ações futuras','',
  '- [ ] Próxima ação, responsável e prazo.'
].join('\n');
const existingDecisionsAndLearnings=String(source.decisionsAndLearnings?.markdown??'').trim();
const decisionsAndLearnings=existingDecisionsAndLearnings||decisionsTemplate;
const componentLines=expectedComponents.map(component=>{
  const label=String(component.name??component.workflowSlug).replace(/[\r\n\[\]]+/g,' ').trim();
  return '- **['+label+'](docs/workflows/'+component.workflowSlug+'.md)** — '+(roleLabels[component.role]??component.role??'Workflow')+'.';
});
const mainFlow=extractSection(technicalMarkdown,'## Fluxo principal');
const inputs=extractSection(technicalMarkdown,'## Gatilhos e entradas');
const outputs=extractSection(technicalMarkdown,'## Saídas');
const integrations=extractSection(technicalMarkdown,'## Integrações e APIs');
const operation=extractSection(technicalMarkdown,'## Operação e observabilidade');
const readme=[
  '# '+safeTitle,'',
  '## Visão geral','',projectSummary,'',
  '## Componentes','',...componentLines,'',
  '## Fluxo principal','',mainFlow,'',
  '## Entradas e saídas','',
  '### Entradas','',inputs,'',
  '### Saídas','',outputs,'',
  '## Integrações','',integrations,'',
  '## Operação','',operation,'',
  '## Arquitetura','',fence+'mermaid',architectureMermaid,fence,'',
  '## Documentação detalhada','',
  '- [Documentação técnica completa](docs/TECHNICAL.md)',
  '- [Contexto interno](docs/INTERNAL.md)',
  '- [Decisões e aprendizados](docs/DECISIONS_AND_LEARNINGS.md)',
  '- [Roteiro de revisão do PR](../README.md#pr-review)',
  '- [Documentação individual dos workflows](docs/workflows/)','',
  'Documentação gerada pelo Bootstrap do n8n. A revisão humana é obrigatória antes da aprovação do PR.'
].join('\n');
const pendingFrom=(markdown,headings)=>headings.filter(heading=>{
  const lines=markdown.split('\n');
  const start=lines.findIndex(line=>line.trim()===heading);
  if(start<0) return false;
  const level=heading.match(/^#+/)?.[0].length??1;
  let end=lines.length;
  for(let index=start+1;index<lines.length;index++){
    const match=lines[index].match(/^(#+)\s/);
    if(match&&match[1].length<=level){end=index;break;}
  }
  return /Precisa de confirmação/i.test(lines.slice(start+1,end).join('\n'));
}).map(heading=>heading.replace(/^#+\s*/,''));
const reviewNotes=[
  ...(Array.isArray(generated.reviewNotes)?generated.reviewNotes.map(String).filter(Boolean):[]),
  ...missingDocuments.map(slug=>'Revisar documento-base determinístico do workflow '+slug+'; a IA omitiu esse item.')
];
const pending=[...new Set([...pendingFrom(internalMarkdown,internalHeadings),...pendingFrom(technicalMarkdown,technicalHeadings),...reviewNotes])];
const pendingChecklist=pending.length
  ? pending.map(item=>'- [ ] '+item.replace(/[\r\n]+/g,' ').trim()).join('\n')
  : '- [x] Nenhuma pendência explícita foi detectada; ainda assim, valide todo o conteúdo.';
const startMarker='<!-- n8n-docs:pr-review:start -->';
const endMarker='<!-- n8n-docs:pr-review:end -->';
const reviewSection=[
  startMarker,'',
  '<a id="pr-review"></a>','',
  '## Roteiro de revisão dos PRs de documentação n8n','',
  '### Objetivo','',
  'Orientar quem completa, revisa e aprova a documentação gerada pelo Bootstrap antes do merge.','',
  '### Estrutura que deve ser revisada','',
  '- `projects/<slug>/README.md`: visão geral e links.',
  '- `projects/<slug>/docs/TECHNICAL.md`: arquitetura e operação.',
  '- `projects/<slug>/docs/INTERNAL.md`: dados humanos e organizacionais.',
  '- `projects/<slug>/docs/DECISIONS_AND_LEARNINGS.md`: decisões, aprendizados e ações futuras.',
  '- `projects/<slug>/docs/workflows/`: detalhes de cada workflow.','',
  '### Dados humanos obrigatórios','',
  '- [ ] Nome e tipo do projeto.',
  '- [ ] Data de início e término ou status atual.',
  '- [ ] Responsáveis e seus papéis.',
  '- [ ] Cliente, empresa ou confirmação de que não se aplica.',
  '- [ ] Relacionamento, prazos, frequência de respostas e pedidos fora do escopo.',
  '- [ ] Escopo, decisões, riscos e pendências internas.',
  '- [ ] Decisões e aprendizados relevantes foram registrados ou marcados como não aplicáveis.','',
  '### Validação técnica','',
  '- [ ] Arquitetura e dependências correspondem aos workflows reais.',
  '- [ ] Gatilhos, entradas, integrações, dados, saídas e erros estão corretos.',
  '- [ ] O Mermaid renderiza no GitHub.',
  '- [ ] Cada workflow do `project.json` possui documento individual.','',
  '### Segurança','',
  '- [ ] Não existem tokens, senhas, IDs privados ou URLs internas.',
  '- [ ] Credenciais são citadas somente por tipo.',
  '- [ ] Dados pessoais e empresariais estão adequados à visibilidade do repositório.','',
  '### Como preparar o PR','',
  '1. Substitua `Precisa de confirmação` por informação validada ou por `Não se aplica`.',
  '2. Faça as correções na mesma branch do PR.',
  '3. Revise o diff completo e confirme que arquivos humanos não foram removidos indevidamente.',
  '4. Marque o PR como pronto para revisão e solicite o aprovador responsável.','',
  '### Critérios para aprovação','',
  '- [ ] Todos os dados obrigatórios foram preenchidos.',
  '- [ ] Documento técnico validado por quem conhece a automação.',
  '- [ ] Documento interno validado por quem conhece o projeto ou cliente.',
  '- [ ] Verificação de segurança concluída.',
  '- [ ] Links e Mermaid renderizam corretamente.','',
  '### Como finalizar','',
  'Aprove o PR conforme a política da equipe e prefira **Squash and merge** para consolidar os commits automáticos e humanos. Depois do merge, a Maintenance altera somente workflows sanitizados e `project.json`.','',
  endMarker
].join('\n');
const existingProjectsReadme=String(source.projectsIndexReadme?.markdown??'').trim();
let projectsReadme=existingProjectsReadme||'# Projetos documentados';
const startIndex=projectsReadme.indexOf(startMarker);
const endIndex=projectsReadme.indexOf(endMarker);
if((startIndex>=0)!==(endIndex>=0)||endIndex>=0&&endIndex<startIndex){
  throw new Error('projects/README.md contém marcadores incompletos ou fora de ordem para a seção pr-review.');
}
if(startIndex>=0){
  const before=projectsReadme.slice(0,startIndex).trimEnd();
  const after=projectsReadme.slice(endIndex+endMarker.length).trimStart();
  projectsReadme=before+'\n\n'+reviewSection+(after?'\n\n'+after:'');
}else{
  projectsReadme=projectsReadme.trimEnd()+'\n\n'+reviewSection;
}
const humanFiles={
  'README.md':readme+'\n',
  'docs/TECHNICAL.md':technicalWithGenerated+'\n',
  'docs/INTERNAL.md':internalMarkdown+'\n',
  'docs/DECISIONS_AND_LEARNINGS.md':decisionsAndLearnings+'\n'
};
const repositoryFiles={'projects/README.md':projectsReadme.trim()+'\n'};
const repositoryDeletePaths=source.legacyReviewFileExists?['PR_REVIEW.md']:[];
for(const component of expectedComponents){
  humanFiles['docs/workflows/'+component.workflowSlug+'.md']=documentsBySlug.get(component.workflowSlug)+'\n';
}
const confidence=['low','medium','high'].includes(generated.confidence)?generated.confidence:'low';
const previousDocumentationUsed=Boolean(
  source.previousDocumentation?.readmeMarkdown||source.previousDocumentation?.technicalMarkdown||source.previousDocumentation?.internalMarkdown
);
const {aiInput,previousDocumentation,projectsIndexReadme,decisionsAndLearnings:sourceDecisionsAndLearnings,legacyReviewFileExists,...base}=source;
return {json:{
  ...base,
  documentationLayout:'separated',
  humanFiles,
  repositoryFiles,
  repositoryDeletePaths,
  aiDocumentation:{
    documentationSchemaVersion:2,
    technicalDocumentSchemaVersion:1,
    internalDocumentSchemaVersion:1,
    workflowDocumentSchemaVersion:1,
    decisionsAndLearningsDocumentSchemaVersion:1,
    workflowDocuments:expectedComponents.length,
    aiGeneratedWorkflowDocuments:expectedComponents.length-missingDocuments.length,
    deterministicFallbackWorkflowDocuments:missingDocuments,
    decisionsAndLearningsPreserved:Boolean(existingDecisionsAndLearnings),
    previousDocumentationUsed,
    pendingReviewItems:pending,
    reviewNotes,
    confidence
  },
  reviewRequired:true
}};

const payloads = $input.all().map(item => item.json);
if (payloads.length === 0) throw new Error("Nenhum enriquecimento foi gerado.");
return [{ json: {
  status: "ai-enriched",
  enrichedProjects: payloads.length,
  payloads,
  reviewRequired: true,
  generatedAt: new Date().toISOString()
}}];

const notion=$json.notionContext??{enabled:false,status:'not-configured'};
const {notionContext,notionRootUrl,...project}=$json;
const notionSummary={
  enabled:Boolean(notion.enabled),
  status:String(notion.status??'not-configured'),
  collectedAt:notion.collectedAt??null,
  pagesProcessed:Number(notion.pagesProcessed??0),
  pagesDiscovered:Number(notion.pagesDiscovered??0),
  summarized:Boolean(notion.summarized),
  summarizedPages:Number(notion.summarizedPages??0),
  summaryFallbacks:Number(notion.summaryFallbacks??0),
  contentHash:notion.contentHash??null,
  truncated:Boolean(notion.truncated),
  contentPublished:false
};
return {json:{
  ...project,
  contextSources:{...(project.contextSources??{}),notion:notionSummary}
}};
